#include "course_test.hpp"
#include "checked_numeric.hpp"
#include <array>
#include <limits>
#include <span>
#include <vector>

int main() {
    using harbor::numeric::Integer;
    using harbor::numeric::checked_add;
    using harbor::numeric::checked_total;
    static_assert(Integer<int> && Integer<unsigned long>);
    static_assert(!Integer<bool> && !Integer<const bool> && !Integer<double>);
    static_assert(checked_add(2, 3) == 5);
    CHECK(checked_total<int>({}) == 0);
    const std::array mixed{10, -4, 7, -3};
    CHECK(checked_total<int>(mixed) == 10);
    constexpr int high = std::numeric_limits<int>::max();
    constexpr int low = std::numeric_limits<int>::min();
    CHECK(checked_add(high, 0) == high);
    CHECK(checked_add(low, 0) == low);
    CHECK(checked_add(high, -1) == high - 1);
    CHECK(checked_add(low, 1) == low + 1);
    CHECK(course::throws<std::overflow_error>([&] { (void)checked_add(high, 1); }));
    CHECK(course::throws<std::overflow_error>([&] { (void)checked_add(low, -1); }));
    const std::vector<int> overflow{high - 2, 1, 2};
    CHECK(course::throws<std::overflow_error>([&] { (void)checked_total<int>(overflow); }));
    CHECK(overflow == std::vector<int>({high - 2, 1, 2}));
    CHECK(course::throws<std::overflow_error>([] {
        (void)checked_add(std::numeric_limits<unsigned>::max(), 1U);
    }));
    // Independent wider arithmetic oracle over a small exhaustive domain.
    for (int left = -40; left <= 40; ++left) {
        for (int right = -40; right <= 40; ++right) {
            const auto actual = checked_add(static_cast<signed char>(left),
                                            static_cast<signed char>(right));
            const int expected = left + right; // Always within [-80,80].
            CHECK(static_cast<int>(actual) == expected);
        }
    }
    course::report();
}

#include "course_test.hpp"
#include <algorithm>
#include <array>
#include <ranges>
#include <span>
#include <string>
#include <string_view>
#include <type_traits>
#include <vector>

std::vector<int> selected_snapshot() {
    std::vector<int> local{1, 2, 3, 4, 5, 6};
    auto view = local | std::views::filter([](int value) { return value % 2 == 0; })
                      | std::views::transform([](int value) { return value * value; });
    std::vector<int> owned;
    for (int value : view) owned.push_back(value);
    return owned; // No borrow of local storage escapes.
}
int main() {
    static_assert(std::ranges::borrowed_range<std::span<int>>);
    static_assert(!std::ranges::borrowed_range<std::vector<int>>);
    using UnsafeResult = decltype(std::ranges::find(std::vector<int>{1, 2}, 2));
    static_assert(std::is_same_v<UnsafeResult, std::ranges::dangling>);
    std::array data{2, 4, 6};
    auto found = std::ranges::find(std::span<int>{data}, 4);
    CHECK(found != std::span<int>{data}.end() && *found == 4);
    const auto snapshot = selected_snapshot();
    CHECK(snapshot == std::vector<int>({4, 16, 36}));
    std::vector<int> source{1, 2, 3, 4};
    {
        auto selected = source | std::views::filter([](int value) { return value % 2 == 0; });
        std::vector<int> captured;
        for (int value : selected) captured.push_back(value);
        CHECK(captured == std::vector<int>({2, 4}));
    } // The old view is no longer used after source changes.
    source[0] = 8;
    auto current = source | std::views::filter([](int value) { return value % 2 == 0; });
    CHECK(*current.begin() == 8);
    std::string line{"17|first title"};
    std::string saved;
    {
        const std::string_view field{line.data() + 3, line.size() - 3};
        saved = std::string{field};
    }
    line.assign(200, 'x');
    CHECK(saved == "first title");
    std::vector<int> empty;
    auto empty_view = empty | std::views::filter([](int v) { return v > 0; });
    CHECK(empty_view.begin() == empty_view.end());
    const std::vector<int> none{-3, -2, -1};
    auto no_matches = none | std::views::filter([](int v) { return v > 0; });
    CHECK(no_matches.begin() == no_matches.end());
    course::report();
}

